-- HS concordance at 6-digit level (audit "HS concordance seeded at chapter level only").
--
-- Source: UN Statistics Division "Conversion and Correlation Tables" (free, official, no key),
-- https://unstats.un.org/unsd/classifications/Econ/tables/ -- HS2022 -> HS2017 and HS2017 -> HS2012.
-- Each row keeps the workbook it came from (source_url, source_sha256); the statements below were
-- produced by `python -m steward.reference.hs_concordance fetch <from> <to> --emit-sql`, which
-- validates the workbook's own relationship labels against the degree of its pairs first, so the
-- seed is reproducible from the published files.  The reverse direction is read by swapping the
-- columns and inverting 1:n / n:1 (steward.reference.hs_concordance.equivalence); chapters keep
-- their existing 'chapter' rows.  Additive: two nullable columns and new rows only.

alter table public.hs_concordance
  add column if not exists source_url text,
  add column if not exists source_sha256 text;

create index if not exists hs_concordance_to_code
  on public.hs_concordance (to_revision, from_revision, to_code);

insert into public.hs_concordance(from_revision, from_code, to_revision, to_code, relation, note, source_url, source_sha256)
